"use strict";exports.normalizeAuthorsNote=function(t){const o={promptText:"",interval:1,depth:4,position:1,role:"system"};if(!t||"object"!=typeof t)return o;const e="string"==typeof t.promptText?t.promptText:"string"==typeof t.prompt?t.prompt:o.promptText,r=Number(t.interval),i=Number(t.depth),p=0===t.position||1===t.position||2===t.position?t.position:o.position,s="user"===t.role||"assistant"===t.role||"system"===t.role?t.role:o.role;return{promptText:e,interval:Number.isFinite(r)&&r>0?Math.floor(r):o.interval,depth:Number.isFinite(i)?Math.floor(i):o.depth,position:p,role:s}};
